pitfalls.badSnippet:
// Transforms accumulate every frame, spinning objects wildly offscreen
ctx.translate(cx, cy);
ctx.rotate(angle);
ctx.fillRect(-40, -40, 80, 80);

pitfalls.goodSnippet:
// Always isolate local transforms in a save/restore bracket
ctx.save();
ctx.translate(cx, cy);
ctx.rotate(angle);
ctx.fillRect(-40, -40, 80, 80);
ctx.restore();

pitfalls.badSnippet:
// Swings the shape in an orbital arc around the canvas top-left corner
ctx.rotate(angle);
ctx.translate(cx, cy);

pitfalls.goodSnippet:
// Move the origin to the target pivot point first, then rotate in place
ctx.translate(cx, cy);
ctx.rotate(angle);
